def shift_down(grid, bg=None, drop=True):
    """Shift every non-background cell down one row; cells leaving the bottom are dropped (or wrap to top if drop=False)."""
    if bg is None:
        bg = max({v for row in grid for v in row}, key=lambda v: sum(r.count(v) for r in grid))
    h, w = len(grid), len(grid[0])
    out = [[bg] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                nr = r + 1
                if nr < h:
                    out[nr][c] = grid[r][c]
                elif not drop:
                    out[0][c] = grid[r][c]
    return out

